import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('exportCsv with single issued invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET30',
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const csv = exportCsv([issuedResult.value]);

  assert.ok(csv.includes('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n'));
  assert.ok(csv.includes('INV-2024-0001'));
  assert.ok(csv.includes('Northwind Studio'));
  assert.ok(csv.includes('2024-01-15'));
  assert.ok(csv.includes('2024-02-14'));
  assert.ok(csv.includes('issued'));
});

test('exportCsv includes subtotal with 2 decimals', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const csv = exportCsv([issuedResult.value]);

  // Subtotal: 10 * 8500 = 85000 cents = 850.00 euros
  assert.ok(csv.includes('850.00'));
});

test('exportCsv includes discount with 2 decimals', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const csv = exportCsv([issuedResult.value]);

  // Discount: 85000 * 10% = 8500 cents = 85.00 euros
  assert.ok(csv.includes('85.00'));
});

test('exportCsv includes VAT with 2 decimals', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const csv = exportCsv([issuedResult.value]);

  // Subtotal: 85000, VAT: 85000 * 21% = 17850 cents = 178.50 euros
  assert.ok(csv.includes('178.50'));
});

test('exportCsv includes total with 2 decimals', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'STICKER', qty: 100, discountPercent: 0 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const csv = exportCsv([issuedResult.value]);

  // STICKER: 100 * 50 = 5000, VAT: 5000 * 21% = 1050, Total: 6050 = 60.50 euros
  assert.ok(csv.includes('60.50'));
});

test('exportCsv includes due amount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'STICKER', qty: 100, discountPercent: 0 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const csv = exportCsv([issuedResult.value]);

  // Due should equal total (6050 cents = 60.50 euros)
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  assert.equal(fields[9], '60.50');
});

test('exportCsv with draft invoice shows DRAFT as number', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  const csv = exportCsv([invoiceResult.value]);

  assert.ok(csv.includes('DRAFT'));
  assert.ok(csv.includes('draft'));
});

test('exportCsv escapes fields with commas', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-004',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const csv = exportCsv([issuedResult.value]);

  // Customer C-004 is "Smith, Jones & Partners"
  assert.ok(csv.includes('"Smith, Jones & Partners"'));
});

test('exportCsv escapes fields with quotes', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-006',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const csv = exportCsv([issuedResult.value]);

  // Customer C-006 is Marlow "The Print Shop"
  // Should be escaped as: Marlow ""The Print Shop""
  assert.ok(csv.includes('Marlow ""The Print Shop""'));
});

test('exportCsv with partially paid invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'STICKER', qty: 100, discountPercent: 0 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const paymentResult = recordPayment(issuedResult.value, { amount: 3000, date: '2024-01-20' });

  const csv = exportCsv([paymentResult.value]);

  assert.ok(csv.includes('partially_paid'));
  // Total: 6050, Paid: 3000, Due: 3050 = 30.50 euros
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  assert.equal(fields[9], '30.50');
});

test('exportCsv with fully paid invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'STICKER', qty: 100, discountPercent: 0 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const paymentResult = recordPayment(issuedResult.value, { amount: 6050, date: '2024-01-20' });

  const csv = exportCsv([paymentResult.value]);

  assert.ok(csv.includes('paid'));
  // Due should be 0.00
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  assert.equal(fields[9], '0.00');
});

test('exportCsv with multiple invoices', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-20',
    lines: [{ sku: 'PRINT-A4', qty: 50 }],
  });

  const issued1 = issueInvoice(inv1Result.value, []);
  const issued2 = issueInvoice(inv2Result.value, ['INV-2024-0001']);

  const csv = exportCsv([issued1.value, issued2.value]);

  assert.ok(csv.includes('INV-2024-0001'));
  assert.ok(csv.includes('INV-2024-0002'));
  assert.ok(csv.includes('Northwind Studio'));
  assert.ok(csv.includes('Blue Fern Bakery'));
});

test('exportCsv with multiple invoices preserves order', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-20',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  const issued1 = issueInvoice(inv1Result.value, []);
  const issued2 = issueInvoice(inv2Result.value, ['INV-2024-0001']);

  const csv = exportCsv([issued1.value, issued2.value]);

  const lines = csv.split('\n');
  // Header + 2 invoices
  assert.equal(lines.length, 4);
  assert.ok(lines[1].includes('INV-2024-0001'));
  assert.ok(lines[2].includes('INV-2024-0002'));
});

test('exportCsv has correct number of fields', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const csv = exportCsv([issuedResult.value]);

  const lines = csv.split('\n');
  const headerFields = lines[0].split(',');
  const dataFields = lines[1].split(',');

  assert.equal(headerFields.length, 10);
  assert.equal(dataFields.length, 10);
});

test('exportCsv ends with newline', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const csv = exportCsv([issuedResult.value]);

  assert.ok(csv.endsWith('\n'));
});

test('exportCsv with empty array', () => {
  const csv = exportCsv([]);

  assert.ok(csv.includes('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n'));
  // Only header, no data lines
  assert.equal(csv, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

test('exportCsv with zero discount shows 0.00', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'STICKER', qty: 100, discountPercent: 0 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const csv = exportCsv([issuedResult.value]);

  const lines = csv.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[5], '0.00');
});

test('exportCsv with different customer tiers', () => {
  const goldResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  const standardResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  const gold = issueInvoice(goldResult.value, []);
  const standard = issueInvoice(standardResult.value, ['INV-2024-0001']);

  const csv = exportCsv([gold.value, standard.value]);

  // Gold customer gets 5% discount, standard gets 0%
  // Gold subtotal: 85000, discount: 4250
  // Standard subtotal: 85000, discount: 0
  const lines = csv.split('\n');
  const goldFields = lines[1].split(',');
  const standardFields = lines[2].split(',');

  assert.equal(goldFields[5], '42.50');
  assert.equal(standardFields[5], '0.00');
});

test('exportCsv with negative balance due shows correct format', () => {
  // This shouldn't happen in normal operation, but test that formatting works
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'PRINT-A4', qty: 1 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const csv = exportCsv([issuedResult.value]);

  // Verify amounts are formatted correctly
  const lines = csv.split('\n');
  const fields = lines[1].split(',');

  // All amounts should have 2 decimal places
  for (let i = 5; i < 10; i++) {
    assert.ok(/^\d+\.\d{2}$/.test(fields[i]) || fields[i] === '0.00', `Field ${i} should be formatted as euros: ${fields[i]}`);
  }
});

test('exportCsv field order is correct', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const csv = exportCsv([issuedResult.value]);

  const lines = csv.split('\n');
  const header = lines[0].split(',');

  assert.equal(header[0], 'number');
  assert.equal(header[1], 'customer');
  assert.equal(header[2], 'issueDate');
  assert.equal(header[3], 'dueDate');
  assert.equal(header[4], 'status');
  assert.equal(header[5], 'subtotal');
  assert.equal(header[6], 'discount');
  assert.equal(header[7], 'vat');
  assert.equal(header[8], 'total');
  assert.equal(header[9], 'due');
});

test('exportCsv with amount containing cents', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'PRINT-A4', qty: 37 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const csv = exportCsv([issuedResult.value]);

  // PRINT-A4: 37 * 37 = 1369, VAT at 9%: 123, Total: 1492 = 14.92 euros
  assert.ok(csv.includes('14.92'));
});

